<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Carbon;
use Tests\TestCase;
class TeamTest extends TestCase {
 use RefreshDatabase;
 private function setupTeam(): array{
  $owner=User::factory()->create(['timezone'=>'Asia/Dhaka']);$admin=User::factory()->create();$manager=User::factory()->create();$member=User::factory()->create(['timezone'=>'Asia/Dhaka']);$peer=User::factory()->create();
  $w=Workspace::create(['name'=>'Example company','type'=>'business','owner_id'=>$owner->id]);$w->members()->attach([$owner->id=>['role'=>'owner'],$admin->id=>['role'=>'admin'],$manager->id=>['role'=>'manager'],$member->id=>['role'=>'member'],$peer->id=>['role'=>'member']]);return [$w,$owner,$admin,$manager,$member,$peer];
 }
 private function login(User $u,Workspace $w): static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function at(string $time): void{$this->travelTo(Carbon::parse($time,'UTC'));}
 private function leaveData(): array{return ['start_date'=>'2026-11-28','end_date'=>'2026-11-30','category'=>'annual','reason'=>'Private leave reason'];}
 public function test_guest_and_personal_workspace_denied(): void{$this->get('/team')->assertRedirect('/login');$u=User::factory()->create();$this->login($u,Identity::personal($u))->get('/team')->assertForbidden();}
 public function test_directory_department_and_profile_permissions(): void{[$w,$owner,$admin,$manager,$member]=$this->setupTeam();$this->login($owner,$w)->post('/team/departments',['name'=>'Engineering'])->assertRedirect();$id=DB::table('departments')->value('id');$this->put('/team/profiles/'.$member->id,['designation'=>'Developer','department_id'=>$id,'responsibilities'=>'Maintain services'])->assertRedirect();$this->login($member,$w)->get('/team')->assertOk()->assertSee('Developer')->assertSee('Engineering');$this->post('/team/departments',['name'=>'Forbidden'])->assertForbidden();$this->put('/team/profiles/'.$member->id,['designation'=>'Owner'])->assertForbidden();$this->login($admin,$w)->put('/team/profiles/'.$owner->id,['designation'=>'Owner'])->assertForbidden();}
 public function test_attendance_uses_server_time_and_rejects_duplicates(): void{[$w,$owner,$admin,$manager,$member]=$this->setupTeam();$this->at('2026-11-27 03:00:00');$this->login($member,$w)->post('/team/attendance',['action'=>'in','user_id'=>$owner->id])->assertRedirect();$this->post('/team/attendance',['action'=>'in'])->assertSessionHasErrors('action');$this->at('2026-11-27 05:30:00');$this->post('/team/attendance',['action'=>'out'])->assertRedirect();$this->post('/team/attendance',['action'=>'out'])->assertSessionHasErrors('action');$a=DB::table('attendance_entries')->first();$this->assertSame($member->id,$a->user_id);$this->assertSame('2026-11-27 05:30:00',$a->checked_out_at);$this->get('/team')->assertOk()->assertSee('2.50 hours');}
 public function test_leave_overlap_and_hierarchical_approval(): void{[$w,$owner,$admin,$manager,$member]=$this->setupTeam();$this->at('2026-11-27 03:00:00');$this->login($member,$w)->post('/team/leave',$this->leaveData())->assertRedirect();$id=DB::table('leave_requests')->value('id');$this->post('/team/leave',$this->leaveData())->assertSessionHasErrors('start_date');$this->patch('/team/leave/'.$id,['status'=>'approved'])->assertForbidden();$this->login($manager,$w)->patch('/team/leave/'.$id,['status'=>'approved'])->assertRedirect();$this->assertDatabaseHas('leave_requests',['id'=>$id,'status'=>'approved','reviewer_id'=>$manager->id]);$this->patch('/team/leave/'.$id,['status'=>'rejected'])->assertSessionHasErrors('status');}
 public function test_peer_leave_reports_and_reviews_are_private(): void{[$w,$owner,$admin,$manager,$member,$peer]=$this->setupTeam();$this->at('2026-11-27 03:00:00');$this->login($member,$w)->post('/team/leave',$this->leaveData())->assertRedirect();$this->post('/team/reports',['local_date'=>'2026-11-27','summary'=>'Secret report summary'])->assertRedirect();$this->login($manager,$w)->post('/team/reviews',['user_id'=>$member->id,'period'=>'November','rating'=>4,'feedback'=>'Confidential feedback'])->assertRedirect();$this->login($peer,$w)->get('/team')->assertOk()->assertDontSee('Secret report summary')->assertDontSee('Private leave reason')->assertDontSee('Confidential feedback');$this->login($member,$w)->get('/team')->assertOk()->assertSee('Confidential feedback');}
 public function test_report_upsert_and_future_date_validation(): void{[$w,$owner,$admin,$manager,$member]=$this->setupTeam();$this->at('2026-11-27 20:00:00');$this->login($member,$w)->post('/team/reports',['local_date'=>'2026-11-28','summary'=>'Initial'])->assertRedirect();$this->post('/team/reports',['local_date'=>'2026-11-28','summary'=>'Updated'])->assertRedirect();$this->assertSame(1,DB::table('daily_reports')->count());$this->assertDatabaseHas('daily_reports',['summary'=>'Updated']);$this->post('/team/reports',['local_date'=>'2026-11-29','summary'=>'Future'])->assertSessionHasErrors('local_date');}
 public function test_reviews_and_onboarding_hierarchy(): void{[$w,$owner,$admin,$manager,$member,$peer]=$this->setupTeam();$this->login($manager,$w)->post('/team/reviews',['user_id'=>$admin->id,'period'=>'November','rating'=>4,'feedback'=>'Forbidden'])->assertForbidden();$this->post('/team/reviews',['user_id'=>$member->id,'period'=>'November','rating'=>6,'feedback'=>'Invalid'])->assertSessionHasErrors('rating');$this->post('/team/onboarding',['user_id'=>$member->id,'title'=>'Read handbook'])->assertRedirect();$id=DB::table('onboarding_items')->value('id');$this->login($peer,$w)->patch('/team/onboarding/'.$id,['completed'=>1])->assertForbidden();$this->login($member,$w)->patch('/team/onboarding/'.$id,['completed'=>1])->assertRedirect();$this->assertNotNull(DB::table('onboarding_items')->value('completed_at'));}
 public function test_documents_private_and_upload_restricted(): void{Storage::fake('local');[$w,$owner,$admin,$manager,$member,$peer]=$this->setupTeam();$this->login($owner,$w)->post('/team/documents',['user_id'=>$member->id,'file'=>UploadedFile::fake()->createWithContent('contract.txt','example contract')])->assertRedirect();$d=DB::table('employee_documents')->first();Storage::disk('local')->assertExists($d->path);$this->login($member,$w)->get('/team/documents/'.$d->id)->assertOk()->assertDownload('contract.txt');$this->login($manager,$w)->get('/team/documents/'.$d->id)->assertNotFound();$this->login($peer,$w)->get('/team/documents/'.$d->id)->assertNotFound();$this->post('/team/documents',['user_id'=>$peer->id,'file'=>UploadedFile::fake()->createWithContent('file.txt','text')])->assertForbidden();$this->login($owner,$w)->delete('/team/documents/'.$d->id)->assertRedirect();Storage::disk('local')->assertMissing($d->path);}
 public function test_cross_workspace_and_removed_members_denied(): void{[$w,$owner,$admin,$manager,$member]=$this->setupTeam();$this->at('2026-11-27 03:00:00');$this->login($member,$w)->post('/team/leave',$this->leaveData())->assertRedirect();$id=DB::table('leave_requests')->value('id');[$other,$otherOwner]=$this->setupTeam();$this->login($otherOwner,$other)->patch('/team/leave/'.$id,['status'=>'approved'])->assertNotFound();$this->put('/team/profiles/'.$member->id,['designation'=>'Foreign'])->assertNotFound();$w->members()->detach($member->id);$this->login($member,$w)->get('/team')->assertForbidden();}
 public function test_announcements_and_dashboard_safe(): void{[$w,$owner,$admin,$manager,$member]=$this->setupTeam();$this->login($member,$w)->post('/team/announcements',['title'=>'Forbidden','body'=>'No'])->assertForbidden();$this->login($manager,$w)->post('/team/announcements',['title'=>'Team update','body'=>'<script>alert(1)</script>'])->assertRedirect();$this->login($member,$w)->get('/team')->assertOk()->assertSee('Team update')->assertDontSee('<script>alert(1)</script>',false)->assertHeader('Cache-Control','no-store, private');$this->get('/dashboard')->assertOk()->assertSee('Team management');}
}
